    user_id uuid NOT NULL,
    meta_enc bytea NOT NULL,
    well_count integer DEFAULT 0 NOT NULL,
    head_rev bigint DEFAULT 0 NOT NULL,
    head_core bytea,
    head_vhash bytea,
    head_bytes bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    modified_at timestamp with time zone NOT NULL,
    deleted_at timestamp with time zone,
    is_conflict_of uuid
);

ALTER TABLE ONLY wts.projects FORCE ROW LEVEL SECURITY;

ALTER TABLE wts.projects OWNER TO wts_owner;

CREATE TABLE wts.push_receipts (
    user_id uuid NOT NULL,
    push_id uuid NOT NULL,
    result jsonb NOT NULL,
    at timestamp with time zone NOT NULL
);

ALTER TABLE ONLY wts.push_receipts FORCE ROW LEVEL SECURITY;

ALTER TABLE wts.push_receipts OWNER TO wts_owner;

CREATE TABLE wts.rate_counters (
    bucket text NOT NULL,
    window_start timestamp with time zone NOT NULL,
    n bigint NOT NULL
);

ALTER TABLE ONLY wts.rate_counters FORCE ROW LEVEL SECURITY;

ALTER TABLE wts.rate_counters OWNER TO wts_owner;

CREATE TABLE wts.revisions (
    project_id uuid NOT NULL,
    user_id uuid NOT NULL,
    rev bigint NOT NULL,
    core_hash bytea NOT NULL,
    vhash bytea NOT NULL,
    parts jsonb NOT NULL,
    bytes bigint NOT NULL,
    device_id uuid,
    session_hash bytea,
    reason text NOT NULL,
    app_ver text,
    saved_at timestamp with time zone NOT NULL,
    pinned boolean DEFAULT false NOT NULL,
    squashed_into bigint,
    pinned_until timestamp with time zone,
    CONSTRAINT revisions_reason_check CHECK ((reason = ANY (ARRAY['auto'::text, 'save'::text, 'migrate'::text, 'conflict'::text, 'restore'::text, 'overwrite'::text, 'import'::text])))
);

ALTER TABLE ONLY wts.revisions FORCE ROW LEVEL SECURITY;

ALTER TABLE wts.revisions OWNER TO wts_owner;

CREATE TABLE wts.sessions (
    sid_hash bytea NOT NULL,
    user_id uuid NOT NULL,
    device_id uuid,
    public_device boolean NOT NULL,
    created_at timestamp with time zone NOT NULL,
    auth_at timestamp with time zone NOT NULL,
    stepup_at timestamp with time zone,
    last_seen_at timestamp with time zone NOT NULL,
    idle_expires_at timestamp with time zone NOT NULL,
    abs_expires_at timestamp with time zone NOT NULL,
    auth_method text DEFAULT 'code'::text NOT NULL,
    identity_id uuid,
    replaced_by bytea,
    replaced_at timestamp with time zone,
    ip_prefix inet,
    ua_family text,
    read_unlock_until timestamp with time zone,
    CONSTRAINT sessions_auth_method_check CHECK ((auth_method = ANY (ARRAY['code'::text, 'google'::text, 'linkedin'::text, 'passkey'::text])))
);

ALTER TABLE ONLY wts.sessions FORCE ROW LEVEL SECURITY;

ALTER TABLE wts.sessions OWNER TO wts_owner;

CREATE TABLE wts.signup_allowlist (
    email_bidx bytea NOT NULL,
    added_at timestamp with time zone NOT NULL,
    note text
);

ALTER TABLE ONLY wts.signup_allowlist FORCE ROW LEVEL SECURITY;

ALTER TABLE wts.signup_allowlist OWNER TO wts_owner;

CREATE TABLE wts.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid GENERATED ALWAYS AS (id) STORED,
    email_bidx bytea NOT NULL,
    email_enc bytea NOT NULL,
    recovery_bidx bytea,
    recovery_enc bytea,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_sign_in_at timestamp with time zone,
    signup_method text DEFAULT 'code'::text NOT NULL,
    terms_version text NOT NULL,
    privacy_version text NOT NULL,
    consented_at timestamp with time zone NOT NULL,
    quota_bytes bigint DEFAULT 250000000 NOT NULL,
    used_bytes bigint DEFAULT 0 NOT NULL,
    opt_historian boolean DEFAULT false NOT NULL,
    opt_livecfg boolean DEFAULT false NOT NULL,
    data_key_wrapped bytea NOT NULL,
    data_key_kid integer NOT NULL,
    data_key_ver integer DEFAULT 1 NOT NULL,
    outbox_key_enc bytea,
    lib_rev bigint DEFAULT 0 NOT NULL,
    lib_hash bytea,
    delete_requested_at timestamp with time zone,
    delete_at timestamp with time zone,
    inactivity_warned_at timestamp with time zone,
    email_changed_at timestamp with time zone,
    email_prev_bidx bytea,
    email_prev_enc bytea,
    email_revert_until timestamp with time zone,
    email_pending_enc bytea,
    recovery_pending_enc bytea,
    lib_saved_at timestamp with time zone,
    CONSTRAINT users_signup_method_check CHECK ((signup_method = ANY (ARRAY['code'::text, 'google'::text, 'linkedin'::text]))),
    CONSTRAINT users_status_check CHECK ((status = ANY (ARRAY['active'::text, 'locked'::text, 'deleting'::text])))
);

ALTER TABLE ONLY wts.users FORCE ROW LEVEL SECURITY;

ALTER TABLE wts.users OWNER TO wts_owner;

