CREATE INDEX audit_subject ON wts.audit USING btree (((detail ->> 'subject_bidx'::text))) WHERE (detail ? 'subject_bidx'::text);

CREATE INDEX audit_user_at ON wts.audit USING btree (user_id, at);

CREATE INDEX email_codes_live ON wts.email_codes USING btree (email_bidx, purpose) WHERE ((used_at IS NULL) AND (invalidated_at IS NULL));

CREATE INDEX oauth_attempts_prefix ON wts.oauth_attempts USING btree (ip_prefix, expires_at);

CREATE INDEX projects_user ON wts.projects USING btree (user_id);

CREATE INDEX revisions_user ON wts.revisions USING btree (user_id);

CREATE INDEX sessions_identity ON wts.sessions USING btree (identity_id) WHERE (identity_id IS NOT NULL);

CREATE INDEX sessions_user ON wts.sessions USING btree (user_id);

